public final class NativeServicesSmokeTest {
    private static int checks;
    private static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
    private static void same(Object a,Object b,String text){check(Objects.equals(a,b),text+": "+a+" != "+b);}
    private static void rejects(Runnable action,String text){try{action.run();throw new AssertionError(text);}catch(IllegalArgumentException|IllegalStateException expected){check(true,text);}}
    private static NativeCampaignV5 campaign(){var c=NativeProgressionScreen.freshCampaign();c.addGold(960);return c;}
    public static void main(String[] args)throws Exception{
        if(args.length>0){var app=new DiagnosticApplication(DiagnosticContent.load(Path.of(args[1])),()->{});app.loadNative(Path.of(args[2]));same(5,app.nativeCampaign().bankGold(),"child bank balance");same(100,app.nativeCampaign().party().get(0).runtime().hp(),"child restored HP");same(10,app.nativeCampaign().party().get(0).runtime().mp(),"child restored MP");same(new WorldPosition(17,9),app.nativeTraversal().position(),"child service return position");System.out.println("NATIVE_SERVICES_CHILD PASS");return;}
        rest();bank();Path root=Files.createTempDirectory("native-service-tests-");try{screens(root);System.out.println("NATIVE_SERVICES checks="+checks+" PASS");}finally{try(var files=Files.walk(root)){for(var p:files.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
    }
    private static void rest(){
        var c=campaign();var a=c.party().get(0);var b=c.party().get(1);a.runtime().damage(5);a.runtime().spendMp(3);a.runtime().setAsleep(true);b.setHp(0);b.runtime().spendMp(2);
        var terms=new InnData(2,"Rest",false);var quote=c.quoteRest(terms);same(13L,quote.cost(),"authored HP rate plus MP cost");same(1,quote.recipients(),"dead guest excluded");same(0,quote.revived(),"no implicit resurrection");
        same(quote,c.rest(terms),"rest uses current quote");same(987L,c.gold(),"inn charged once");same(100,a.runtime().hp(),"same native HP restored");same(10,a.runtime().mp(),"same native MP restored");check(!a.runtime().isAsleep(),"rest clears sleep");same(0,b.runtime().hp(),"dead member stays dead");same(8,b.runtime().mp(),"excluded dead MP unchanged");same(1,a.level(),"rest does not train");check(a.learned().isEmpty(),"rest does not teach moves");same(0L,c.quoteRest(terms).cost(),"healthy non-revival rest has zero cost");
        var revive=new InnData(2,"Revive",true);same(202L,c.quoteRest(revive).cost(),"authored revival quote includes full HP and MP deficit");same(1,c.rest(revive).revived(),"explicit revival applied");same(100,b.runtime().hp(),"revived to full HP");same(10,b.runtime().mp(),"revived MP restored");same(785L,c.gold(),"revival cost exact");
        var poor=NativeProgressionScreen.freshCampaign();poor.party().get(0).runtime().damage(50);rejects(()->poor.rest(terms),"insufficient rest funds rejected");same(40L,poor.gold(),"failed rest no gold debit");same(50,poor.party().get(0).runtime().hp(),"failed rest no HP change");
        var expensive=new InnData(Integer.MAX_VALUE,"Expensive",false);check(poor.quoteRest(expensive).cost()>Integer.MAX_VALUE,"large inn quote uses long");rejects(()->poor.rest(expensive),"large price cannot wrap into free rest");rejects(()->poor.quoteRest(new InnData(-1,null,false)),"negative inn rate rejected");
        var dead=campaign();dead.party().forEach(m->m.setHp(0));same(0,dead.quoteRest(terms).recipients(),"no living guests");rejects(()->dead.rest(terms),"all-dead normal inn makes no transaction");same(1000L,dead.gold(),"all-dead failed rest no gold lost");same(2,dead.rest(revive).revived(),"revival terms handle all eligible dead guests");
        var enemy=EncounterFactory.buildMonster("Service foe",12,1,40);var fight=c.startBattle(List.of(enemy),ignored->10);rejects(()->c.rest(terms),"no inn during combat");rejects(()->c.transferBank(true,1,BankData.standard()),"no bank during combat");enemy.setHp(0);fight.settle();rejects(()->c.rest(terms),"result must be acknowledged before services");fight.acknowledge();
    }
    private static void bank(){
        var c=campaign();var terms=new BankData(10,20);var deposit=c.transferBank(true,101,terms);same(11,deposit.fee(),"deposit fee rounds up");same(90,deposit.credited(),"net deposit");same(899L,c.gold(),"gross purse debit");same(90,c.bankGold(),"net bank credit");
        var withdrawal=c.transferBank(false,50,terms);same(10,withdrawal.fee(),"withdrawal fee");same(40,withdrawal.credited(),"net purse credit");same(939L,c.gold(),"withdrawal gold");same(40,c.bankGold(),"gross bank debit");same(1000L,c.gold()+c.bankGold()+deposit.fee()+withdrawal.fee(),"gold conserved after fees");
        long purse=c.gold();int savedBank=c.bankGold();rejects(()->c.transferBank(true,10000,terms),"insufficient purse no partial transfer");rejects(()->c.transferBank(false,10000,terms),"insufficient bank no partial transfer");same(purse,c.gold(),"failed transfers preserve purse");same(savedBank,c.bankGold(),"failed transfers preserve bank");
        rejects(()->c.transferBank(true,0,terms),"zero transfer rejected");rejects(()->c.transferBank(true,-1,terms),"negative transfer rejected");rejects(()->c.transferBank(true,1,new BankData(101,0)),"invalid fee rejected");rejects(()->c.transferBank(false,1,new BankData(0,-1)),"negative withdrawal fee rejected");same(1,NativeCampaignV5.quoteBank(true,1,new BankData(1,0)).fee(),"fractional fee rounds once");same(0,NativeCampaignV5.quoteBank(true,1,new BankData(100,0)).credited(),"100 percent fee explicitly credits zero");
        var full=campaign();full.transferBank(true,10,BankData.standard());full.addGold(Integer.MAX_VALUE-full.getPartyGold());rejects(()->full.transferBank(false,10,BankData.standard()),"purse overflow rejected before bank debit");same(10,full.bankGold(),"overflow keeps bank gold");same(Integer.MAX_VALUE,full.getPartyGold(),"overflow keeps full purse");
        var s=c.snapshot();var maximum=new NativeCampaignV5.Snapshot(s.members(),s.gold(),Integer.MAX_VALUE,s.pendingGold(),s.readySlots(),s.curriculum(),s.questFlags(),s.worldPosition(),s.pendingChests());var fullBank=NativeCampaignV5.restore(maximum);rejects(()->fullBank.transferBank(true,1,BankData.standard()),"bank overflow rejected before purse debit");same(s.gold(),fullBank.getPartyGold(),"bank overflow leaves purse");same(Integer.MAX_VALUE,fullBank.bankGold(),"bank overflow balance intact");
        var pending=NativeProgressionScreen.freshCampaign();pending.addGold(Integer.MAX_VALUE-40);var enemy=EncounterFactory.buildMonster("Pending foe",12,1,40);var fight=pending.startBattle(List.of(enemy),ignored->10);enemy.setHp(0);fight.acknowledge();same(20L,pending.pendingGold(),"earned gold pending with full purse");pending.transferBank(true,10,BankData.standard());same(Integer.MAX_VALUE,pending.getPartyGold(),"deposit space claims pending gold");same(10,pending.bankGold(),"deposit credited");same(10L,pending.pendingGold(),"pending claim counted once");same((long)Integer.MAX_VALUE+20,pending.gold()+pending.bankGold()+pending.pendingGold(),"deposit and reward retry conserve total");
    }
    private static void key(DiagnosticApplication app,int key){var canvas=new Canvas();app.manager().getActiveScreen().onKeyPressed(new KeyEvent(canvas,KeyEvent.KEY_PRESSED,0,0,key,KeyEvent.CHAR_UNDEFINED));app.manager().update(.2f);app.manager().update(.2f);app.manager().getActiveScreen().onKeyReleased(new KeyEvent(canvas,KeyEvent.KEY_RELEASED,0,0,key,KeyEvent.CHAR_UNDEFINED));}
    private static void render(DiagnosticApplication app,String name)throws Exception{var image=new BufferedImage(GameCanvas.DESIGN_WIDTH,GameCanvas.DESIGN_HEIGHT,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{app.manager().render(g,image.getWidth(),image.getHeight());}finally{g.dispose();}check(image.getRGB(300,300)!=0xff000000,"service render "+name);javax.imageio.ImageIO.write(image,"png",Path.of(System.getProperty("java.io.tmpdir"),"native-service-"+name+".png").toFile());}
    private static void screens(Path root)throws Exception{
        var content=DiagnosticContent.exportAndLoad(DiagnosticContent.create(),root.resolve("content"));var app=new DiagnosticApplication(content,()->{});var legacy=app.session();key(app,KeyEvent.VK_N);var c=app.nativeCampaign();var a=c.party().get(0);a.runtime().damage(5);a.runtime().spendMp(3);walk(app.nativeTraversal(),15,8);var pos=app.nativeTraversal().position();key(app,KeyEvent.VK_DOWN);same(GameState.NATIVE_SERVICE,app.manager().getActiveState(),"mapped inn counter opens native service");render(app,"inn");key(app,KeyEvent.VK_ENTER);same(100,a.runtime().hp(),"counter rest updates exploration HP");same(10,a.runtime().mp(),"counter rest updates native MP");same(27L,c.gold(),"counter authored rate charges 13");key(app,KeyEvent.VK_ENTER);same(27L,c.gold(),"acknowledged inn cannot charge twice");key(app,KeyEvent.VK_ESCAPE);same(GameState.NATIVE_LOCAL_MAP,app.manager().getActiveState(),"inn closes to same map");same(new WorldPosition(15,9),app.nativeTraversal().position(),"inn retains party tile");
        walk(app.nativeTraversal(),16,9);key(app,KeyEvent.VK_RIGHT);same(GameState.NATIVE_SERVICE,app.manager().getActiveState(),"mapped bank counter opens service");key(app,KeyEvent.VK_1);key(app,KeyEvent.VK_0);key(app,KeyEvent.VK_ENTER);same(10,c.bankGold(),"bank UI deposit exact");same(17L,c.gold(),"bank UI purse debit");key(app,KeyEvent.VK_ENTER);same(10,c.bankGold(),"cleared amount prevents repeated transfer");key(app,KeyEvent.VK_W);key(app,KeyEvent.VK_5);key(app,KeyEvent.VK_ENTER);same(5,c.bankGold(),"bank UI withdraw");same(22L,c.gold(),"bank UI purse credit");render(app,"bank");key(app,KeyEvent.VK_ESCAPE);same(new WorldPosition(17,9),app.nativeTraversal().position(),"bank closes at same tile");same(400,legacy.getPartyGold(),"native service never charges legacy purse");same(0,legacy.getLedger().getBankGold(),"legacy bank remains separate");
        var save=root.resolve("services.pns");app.saveNative(save);var raw=Files.readAllBytes(save);same(3,java.nio.ByteBuffer.wrap(raw).getInt(4),"native writer uses save version three");var restored=new DiagnosticApplication(DiagnosticContent.load(root.resolve("content")),()->{});restored.loadNative(save);same(5,restored.nativeCampaign().bankGold(),"bank balance survives checkpoint");same(22L,restored.nativeCampaign().gold(),"purse survives with bank");same(100,restored.nativeCampaign().party().get(0).runtime().hp(),"restored HP survives checkpoint");
        var child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin/java").toString(),"--enable-preview","-Djava.awt.headless=true","-cp",System.getProperty("java.class.path"),NativeServicesSmokeTest.class.getName(),"--child",root.resolve("content").toString(),save.toString()).redirectErrorStream(true).start();check(child.waitFor(30,java.util.concurrent.TimeUnit.SECONDS),"service restart child completes");var output=new String(child.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);check(child.exitValue()==0&&output.contains("NATIVE_SERVICES_CHILD PASS"),"fresh process restores service state: "+output);
        var v2=root.resolve("version-two.pns");Files.write(v2,versionTwo(raw));var previous=new DiagnosticApplication(content,()->{});previous.loadNative(v2);same(5,previous.nativeCampaign().bankGold(),"version-two reader retains bank");check(previous.nativeCampaign().shopState().snapshot().isEmpty(),"version-two reader initializes absent stock history");
        var v1=root.resolve("version-one.pns");Files.write(v1,versionOne(raw));var older=new DiagnosticApplication(content,()->{});older.loadNative(v1);same(0,older.nativeCampaign().bankGold(),"version-one checkpoints initialize absent bank to zero");same(22L,older.nativeCampaign().gold(),"v1 purse retained");same(new WorldPosition(17,9),older.nativeTraversal().position(),"v1 visit retained");
        var snapshot=c.snapshot();var invalid=new NativeCampaignV5.Snapshot(snapshot.members(),snapshot.gold(),-1,snapshot.pendingGold(),snapshot.readySlots(),snapshot.curriculum(),snapshot.questFlags(),snapshot.worldPosition(),snapshot.pendingChests());rejects(()->NativeCampaignV5.restore(invalid),"negative saved bank balance rejected");
        oneShot();npcRoles();
    }
    private static byte[] versionTwo(byte[] file)throws Exception{
        var header=new DataInputStream(new ByteArrayInputStream(file));int magic=header.readInt();int version=header.readInt();var body=header.readNBytes(header.readInt());if(version==2)return file;
        var in=new DataInputStream(new ByteArrayInputStream(body));in.readUTF();in.readInt();in.readInt();in.readLong();in.readInt();in.readLong();in.readInt();in.readInt();
        int steps=in.readInt();for(int i=0;i<steps;i++){in.readUTF();in.readInt();in.readLong();in.readInt();in.readInt();in.readInt();int n=in.readInt();for(int j=0;j<n;j++)in.readUTF();}
        int members=in.readInt();for(int i=0;i<members;i++){in.skipNBytes(64);for(int k=0;k<2;k++){int n=in.readInt();for(int j=0;j<n;j++)in.readUTF();}}
        int chests=in.readInt();for(int i=0;i<chests;i++){for(int j=0;j<4;j++)in.readInt();int n=in.readInt();in.skipNBytes(12L*n);}
        int stockOffset=body.length-in.available();if(in.readInt()!=0)throw new AssertionError("Legacy fixture must have no purchase history");
        var old=new ByteArrayOutputStream();old.write(body,0,stockOffset);old.write(body,stockOffset+4,body.length-stockOffset-4);byte[] payload=old.toByteArray();var result=new ByteArrayOutputStream();var out=new DataOutputStream(result);out.writeInt(magic);out.writeInt(2);out.writeInt(payload.length);out.write(payload);out.write(java.security.MessageDigest.getInstance("SHA-256").digest(payload));return result.toByteArray();
    }
    private static byte[] versionOne(byte[] file)throws Exception{
        file=versionTwo(file);
        var header=new DataInputStream(new ByteArrayInputStream(file));int magic=header.readInt();header.readInt();var body=header.readNBytes(header.readInt());var in=new DataInputStream(new ByteArrayInputStream(body));in.readUTF();in.readInt();int bankOffset=body.length-in.available();
        var old=new ByteArrayOutputStream();old.write(body,0,bankOffset);old.write(body,bankOffset+4,body.length-bankOffset-4);byte[] payload=old.toByteArray();var result=new ByteArrayOutputStream();var out=new DataOutputStream(result);out.writeInt(magic);out.writeInt(1);out.writeInt(payload.length);out.write(payload);out.write(java.security.MessageDigest.getInstance("SHA-256").digest(payload));return result.toByteArray();
    }
    private static void oneShot()throws Exception{
        var content=DiagnosticContent.create();var town=content.maps().get(DiagnosticContent.SETTLEMENT);var old=town.getFeatureAt(17,9);town.removeFeature(old);var flag=QuestFlag.MISC_FLAG_60;town.addFeature(new PlacedFeature(17,9,PlacedFeatureType.BANK_COUNTER,new BankData(10,20),null,flag,null));var app=new DiagnosticApplication(content,()->{});app.enterNative(DiagnosticContent.SETTLEMENT);walk(app.nativeTraversal(),16,9);key(app,KeyEvent.VK_RIGHT);key(app,KeyEvent.VK_ESCAPE);check(!app.nativeCampaign().hasFlag(flag),"leaving without transaction does not consume one-shot service");key(app,KeyEvent.VK_LEFT);key(app,KeyEvent.VK_RIGHT);key(app,KeyEvent.VK_1);key(app,KeyEvent.VK_0);key(app,KeyEvent.VK_ENTER);check(app.nativeCampaign().hasFlag(flag),"successful service consumes authored completion flag");same(9,app.nativeCampaign().bankGold(),"authored bank counter fee applied");key(app,KeyEvent.VK_1);key(app,KeyEvent.VK_ENTER);same(9,app.nativeCampaign().bankGold(),"resolved one-shot overlay cannot transact again");key(app,KeyEvent.VK_ESCAPE);key(app,KeyEvent.VK_LEFT);key(app,KeyEvent.VK_RIGHT);same(GameState.NATIVE_LOCAL_MAP,app.manager().getActiveState(),"consumed counter no longer opens service");
    }
    private static void npcRoles()throws Exception{
        var content=DiagnosticContent.create();var town=content.maps().get(DiagnosticContent.SETTLEMENT);content.npcs().register(new NpcDefinition(9200,"Test innkeeper",NpcRole.INNKEEPER,null));content.npcs().register(new NpcDefinition(9201,"Test banker",NpcRole.BANKER,null));town.addNpc(new PlacedNpc(9200,4,8,Direction.NORTH));town.addNpc(new PlacedNpc(9201,4,10,Direction.NORTH));var app=new DiagnosticApplication(content,()->{});app.enterNative(DiagnosticContent.SETTLEMENT);app.nativeCampaign().party().get(0).runtime().damage(1);walk(app.nativeTraversal(),4,7);key(app,KeyEvent.VK_DOWN);same(GameState.NATIVE_SERVICE,app.manager().getActiveState(),"innkeeper role opens native inn");key(app,KeyEvent.VK_ENTER);same(30L,app.nativeCampaign().gold(),"NPC uses existing standard inn rate ten");key(app,KeyEvent.VK_ESCAPE);walk(app.nativeTraversal(),4,9);key(app,KeyEvent.VK_DOWN);same(GameState.NATIVE_SERVICE,app.manager().getActiveState(),"banker role opens native bank");key(app,KeyEvent.VK_1);key(app,KeyEvent.VK_ENTER);same(1,app.nativeCampaign().bankGold(),"NPC bank default is fee-free");
    }
    private static void walk(LocalMapTraversal t,int tx,int ty){
        var map=t.map();var goal=new WorldPosition(tx,ty);var queue=new ArrayDeque<WorldPosition>();var paths=new HashMap<WorldPosition,List<Direction>>();queue.add(t.position());paths.put(t.position(),List.of());
        while(!queue.isEmpty()&&!paths.containsKey(goal)){var p=queue.remove();for(Direction d:Direction.values()){int dx=d==Direction.EAST?1:d==Direction.WEST?-1:0,dy=d==Direction.SOUTH?1:d==Direction.NORTH?-1:0;var n=new WorldPosition(p.x()+dx,p.y()+dy);if(!map.inBounds(n.x(),n.y())||paths.containsKey(n)||t.visibleNpcAt(n.x(),n.y())!=null)continue;var tile=AuthoredContentValidator.tileSet(map.getTileSetId()).getEntry(map.getTile(n.x(),n.y()));if(!tile.passable()||!n.equals(goal)&&map.getFeatureAt(n.x(),n.y())!=null)continue;var path=new ArrayList<>(paths.get(p));path.add(d);paths.put(n,path);queue.add(n);}}
        if(!paths.containsKey(goal))throw new AssertionError("No test route to "+goal);for(var d:paths.get(goal))t.move(d);
    }
}
